'use strict';
const el=s=>document.querySelector(s),escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>Number(v||0).toLocaleString('en-US',{minimumFractionDigits:Number.isInteger(Number(v))?0:2,maximumFractionDigits:2});
const cats=['薪資','股息','餐飲','交通','生活','保險','娛樂','轉帳','投資','信用卡繳款'];
let db={transactions:[],assets:[],debts:[],imports:[]},summary={},page='dashboard',month='2026-10',pending=[],busy=false,health={},lastError='',fileResults=[],statsRequest=0;
const pages=[['dashboard','財務總覽'],['upload','帳單上傳'],['transactions','交易明細'],['accounts','資產與帳款'],['guide','使用與備份']];
async function api(url,data){let response;try{response=await fetch(url,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data),cache:'no-store'})}catch{throw Error('無法連接本機服務，請確認啟動視窗仍在執行。')}const result=await response.json();if(!response.ok)throw Error(result.error||'操作失敗，資料未確認入帳');return result}
function notice(msg){el('#notice').textContent=msg;el('#notice').hidden=false;clearTimeout(notice.timer);notice.timer=setTimeout(()=>el('#notice').hidden=true,6500)}
async function reload(){const ticket=++statsRequest,requested=month;const [data,stats]=await Promise.all([api('/api/state'),api('/api/stats?month='+encodeURIComponent(requested))]);if(ticket!==statsRequest||requested!==month)return;db=data;summary=stats}
function goto(next){page=next;draw();window.scrollTo(0,0)}
function buttons(){return '<button class="btn primary" data-page="upload">＋ 上傳帳單</button>'}
function header(title,kicker,desc,actions=''){return `<div class="topline"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function monthPicker(){const ms=[...new Set([month,...db.transactions.map(t=>t.date.slice(0,7))])].sort().reverse();return `<select aria-label="統計月份" id="monthPicker">${ms.map(m=>`<option ${m===month?'selected':''}>${escapeHTML(m)}</option>`).join('')}</select>`}
const assetsTotal=()=>db.assets.reduce((n,a)=>n+Number(a.value),0),debtsTotal=()=>db.debts.reduce((n,d)=>n+Number(d.balance),0);
function table(rows,editable=false){return `<div class="tablewrap"><table><thead><tr><th>日期</th><th>交易摘要</th><th>分類</th><th>文件來源</th><th style="text-align:right">TWD</th>${editable?'<th>操作</th>':''}</tr></thead><tbody>${rows.map(t=>`<tr><td class="mono">${escapeHTML(t.date)}</td><td>${escapeHTML(t.name)}</td><td><span class="badge">${escapeHTML(t.category)}</span></td><td><button class="textbtn" data-source="${escapeHTML(t.id)}">${escapeHTML(t.source)}${t.page?' · p.'+escapeHTML(t.page):t.line?' · 列'+escapeHTML(t.line):''}</button></td><td class="amount">${Number(t.amount)>0?'+':''}${fmt(t.amount)}</td>${editable?`<td><button class="textbtn" data-edit="${escapeHTML(t.id)}">編輯</button></td>`:''}</tr>`).join('')||'<tr><td colspan="6" class="empty">還沒有已確認的交易。先上傳一份帳單。</td></tr>'}</tbody></table></div>`}
function brickIntro(){return `<section class="brick-welcome"><div class="brick-welcome-copy"><div class="eyebrow">BUILD A LITTLE. LIVE A LOT.</div><h2>你的財務，<br>一塊一塊看清楚。</h2><p>把銀行帳單、信用卡與薪資，拼成你的財務全貌。</p><div class="brick-role-tags"><span>銀行經理 · 核對帳款</span><span>上班族 · 掌握薪資</span></div></div><figure class="brick-welcome-figure"><img src="assets/brick-finance-team-preview.webp" width="1536" height="1024" alt="積木銀行經理與拿薪資單的積木上班族"><figcaption>認真管錢，也可以有一點玩心。</figcaption></figure></section>`}
function dashboard(){const assets=assetsTotal(),debts=debtsTotal(),i=Number(summary.income||0),e=Number(summary.expense||0);const spending={};db.transactions.filter(t=>t.date.startsWith(month)&&!['轉帳','投資','信用卡繳款','薪資','股息'].includes(t.category)).forEach(t=>spending[t.category]=(spending[t.category]||0)-Number(t.amount));return header('你的數字，真的算清楚。','THE BIG PICTURE','這裡只顯示已覆核、已寫入 SQLite 的資料。',monthPicker()+buttons())+brickIntro()+`<div class="strip"><span><span class="tag">真實資料工作區</span>無示範數字 · 金額由後端以整數分計算</span><span class="mono">${db.transactions.length} RECORDS</span></div><div class="bento"><section class="tile net yellow"><span class="eyebrow">NET WORTH / 資產快照減負債</span><div class="num"><small>NT$</small>${fmt(assets-debts)}</div><div class="note">資產與負債取自文件快照，不將交易流水再次累加。不同日期快照合併時，請先檢查日期與涵蓋帳戶。</div><div class="tiny">只涵蓋已匯入的帳戶；不是對你全部資產的認定。</div></section><section class="tile asset blue"><h2>帳戶資產</h2><span class="eyebrow">ACCOUNT BALANCES</span><div class="statnum num">${fmt(assets)}</div><span class="tiny">${db.assets.length} 個帳戶快照</span></section><section class="tile debt red"><h2>帳單負債</h2><span class="eyebrow">DUE</span><div class="statnum num">${fmt(debts)}</div><span class="tiny">信用卡本期應繳</span></section><section class="tile income"><h2>本月收入</h2><span class="eyebrow">MONEY IN</span><div class="statnum num">${fmt(i)}</div><span class="tiny">淨薪資與其他收入</span></section><section class="tile expense"><h2>本月支出</h2><span class="eyebrow">MONEY OUT</span><div class="statnum num">${fmt(e)}</div><span class="tiny">不重算繳卡費與轉帳</span></section><section class="tile savings"><h2>本月收支結餘</h2><div class="statnum num">${fmt(summary.balance)}</div><div class="tiny">儲蓄率 ${i?((i-e)/i*100).toFixed(1)+'%':'尚無收入記錄'}</div></section><section class="tile pending"><h2>統計涵蓋範圍</h2><div class="statnum num">${summary.transaction_count||0}<small> 筆</small></div><div class="tiny">其中 ${summary.excluded_count||0} 筆為轉帳、投資或繳卡費，不計入收支</div></section><section class="tile goal"><h2>數字可以回查</h2><div class="statnum num">${db.imports.length}<small> 份文件</small></div><button class="textbtn" data-page="transactions">查看交易與來源 ↗</button></section></div><div class="lower"><section class="panel"><div class="section-head"><h2>支出，流向哪裡？</h2><span class="eyebrow">SPENDING</span></div>${Object.entries(spending).map(([c,v])=>`<div class="legend-row"><span>${escapeHTML(c)}</span><strong>${fmt(v)}</strong></div>`).join('')||'<p class="muted">這個月尚無支出記錄。</p>'}</section><section class="panel"><div class="section-head"><h2>入帳前，都先看一眼。</h2><span class="eyebrow">REVIEW FIRST</span></div><p class="sub">薪資單只計實發薪資；扣稅與保險留作明細。銀行與薪資單相同日期、摘要、金額的薪轉會標成疑似重複。</p><p class="sub muted">薪資／股息依分類計收入；消費分類的正數退款會抵減支出。未知版型、掃描 PDF 與加密文件會明確拒絕，不產生猜測金額。</p><button class="btn" data-page="upload">開始匯入 →</button></section></div><div class="section-head"><h2>最近入帳</h2></div>${table(db.transactions.filter(t=>t.date.startsWith(month)).slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6))}`}
function upload(){return header('從一張帳單開始。','DOCUMENT INBOX','上傳檔案，檢查辨識結果，再確認入帳。')+`<div class="upload-zone ${busy?'over':''}" id="dropZone" role="button" tabindex="0" aria-label="選擇PDF或CSV帳單"><div class="upload-icon">↥</div><h2>${busy?'正在本機處理…':'拖曳 PDF / CSV 到這裡'}</h2><p>單檔 5 MiB · 文字型 PDF 最多20頁 · 不傳送至雲端<br>尚不支援手機拍照與掃描 OCR</p><button class="btn primary" id="chooseFiles" ${busy?'disabled':''}>選擇檔案 ＋</button></div><div class="note">目前支援隨包附上的銀行、信用卡與薪資單版型，以及標準 CSV。不是所有銀行版型皆可辨識；不符合版型時會拒絕。請先用 fixtures/pdf 中的合成文件體驗完整流程。</div>${fileResults.map(r=>`<div class="upload-status" role="status" aria-live="polite" style="border-color:${r.ok?'var(--blue)':'var(--red)'}">${escapeHTML(r.message)}</div>`).join('')}${pending.map((d,di)=>`<section class="file-card"><div class="section-head"><h2>${escapeHTML(d.filename||d.metadata?.filename||d.transactions?.[0]?.source||'待覆核文件')}</h2><span class="badge">${escapeHTML(d.kind)}</span></div><p class="sub muted">${d.transactions.length} 筆辨識 · ${d.transactions.filter(t=>t.duplicate).length} 筆疑似重複 · 尚未計入統計</p>${(d.warnings||[]).map(w=>`<div class="note">${escapeHTML(w)}</div>`).join('')}<details><summary>文件核對與薪資明細</summary><pre style="white-space:pre-wrap;font-size:11px">${escapeHTML(JSON.stringify(d.metadata,null,2))}</pre></details>${d.assets?.length||d.debts?.length?'<div class="note">確認時將一併套用此文件的帳戶期末餘額／應繳快照。文件中沒有的帳戶不會被刪除。</div>':''}<div class="tablewrap review"><table><thead><tr><th>入帳</th><th>日期</th><th>摘要</th><th>金額</th><th>分類</th><th>狀態</th></tr></thead><tbody>${d.transactions.map((t,ti)=>`<tr><td><input type="checkbox" data-doc="${di}" data-row="${ti}" data-field="keep" ${busy?'disabled':''} aria-label="保留第${ti+1}筆" ${t.keep?'checked':''}></td><td><input type="date" value="${escapeHTML(t.date)}" data-doc="${di}" data-row="${ti}" data-field="date" ${busy?'disabled':''} aria-label="日期"></td><td><input class="wide" maxlength="150" value="${escapeHTML(t.name)}" data-doc="${di}" data-row="${ti}" data-field="name" ${busy?'disabled':''} aria-label="摘要"></td><td><input type="number" step="0.01" value="${escapeHTML(t.amount)}" data-doc="${di}" data-row="${ti}" data-field="amount" ${busy?'disabled':''} aria-label="金額"></td><td><select data-doc="${di}" data-row="${ti}" data-field="category" ${busy?'disabled':''} aria-label="分類">${cats.map(c=>`<option ${c===t.category?'selected':''}>${c}</option>`).join('')}</select></td><td><span class="badge ${t.duplicate?'pending':''}">${t.duplicate?'疑似重複':'待確認'}</span></td></tr>`).join('')}</tbody></table></div><p class="tiny muted">未勾選的交易不入帳。不同文件若日期、摘要與金額一致會去重；修改後會由後端再次檢查。</p><div class="actions"><button class="btn" data-discard="${di}" ${busy?'disabled':''}>稍後處理</button><button class="btn primary" data-commit="${di}" ${busy?'disabled':''}>確認交易與快照入庫 →</button></div></section>`).join('')}`}
function transactions(){return header('每一筆，都有依據。','TRANSACTION LEDGER','編輯會由後端驗證並寫入資料庫；重載後仍保留。',monthPicker()+'<button class="btn" id="csvExport">匯出本月 CSV ↓</button>')+table(db.transactions.filter(t=>t.date.startsWith(month)).slice().sort((a,b)=>b.date.localeCompare(a.date)),true)}
function accounts(){return header('帳戶與應繳，一起看。','ACCOUNTS & LIABILITIES','以確認文件的期末餘額為快照，不將交易再加一次。')+`<div class="split"><section class="panel"><h2>資產帳戶</h2>${db.imports.flatMap(i=>i.warnings||[]).map(w=>`<div class="note">${escapeHTML(w)}</div>`).join('')}${db.assets.map(a=>`<div class="holding-list"><div class="row"><div><h3>${escapeHTML(a.name||a.account)}</h3><span class="tiny muted">${escapeHTML(a.source)} · ${escapeHTML(a.as_of||'文件快照')}</span></div><strong class="num">${fmt(a.value)}</strong></div></div>`).join('')||'<p class="empty">尚無資產快照</p>'}</section><section class="panel"><h2>信用卡應繳</h2>${db.debts.map(d=>`<div class="holding-list"><div class="row"><div><h3>${escapeHTML(d.name)}</h3><span class="tiny muted">${escapeHTML(d.account||'')} · 截止 ${escapeHTML(d.due)}<br>最低應繳 ${d.minimum_payment===undefined?'未提供':fmt(d.minimum_payment)}</span></div><strong class="num">${fmt(d.payment||d.balance)}</strong></div></div>`).join('')||'<p class="empty">尚無負債快照</p>'}</section></div>`}
function guide(){return header('資料在本機，計算可重現。','LOCAL & VERIFIABLE','本機 Python 後端 + SQLite；沒有銀行帳號串接。')+`<div class="split"><section class="panel"><h2>先試三份合成 PDF</h2><ol class="sub" style="line-height:2.2"><li>匯入 bank-statement.pdf，確認5筆銀行交易。</li><li>匯入 credit-card-statement.pdf，確認3筆消費。</li><li>匯入 payslip.pdf，薪資與銀行重複，預設不再入帳。</li></ol><div class="note">資料庫原本空白時，2026-10應為收入66,200、支出21,800、結餘44,400，8筆唯一交易。銀行餘額134,400；信用卡負債3,800。</div><p class="sub">這是固定合成版型的驗算結果，不等於支援所有銀行或已完成掃描 OCR。</p></section><section class="panel"><h2>文件紀錄與備份</h2>${db.imports.map(i=>`<div class="legend-row"><button class="textbtn" data-document-source="${escapeHTML(i.document_id)}">${escapeHTML(i.name)} ↗</button><strong>${i.count} 筆</strong></div>`).join('')}<p class="sub">服務停止後，可完整複製 data/ledger.sqlite3 備份；也可匯出已入帳資料JSON作檢視。JSON匯出尚未提供一鍵還原。</p><button class="btn primary" id="jsonExport">匯出資料 JSON ↓</button><div class="note">本地資料庫未加密；請使用作業系統的磁碟保護。原始PDF不留存，文件欄位與來源資訊會保存在SQLite。生成式AI、即時行情與新聞尚未串接。</div><p class="tiny muted">此入口使用系統字體，不向外部字體服務連線。</p></section></div>`}
function draw(){el('#navigation').innerHTML=pages.map(([id,name],i)=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><b>0${i+1}</b>${name}</button>`).join('');el('#content').innerHTML=(lastError?`<div class="note" role="alert">${escapeHTML(lastError)}</div>`:'')+({dashboard,upload,transactions,accounts,guide}[page]||dashboard)()+'<div class="footer"><span>帳見 LEDGER. 看懂數字，再做決定。</span><span class="mono">PYTHON + SQLITE / LOCAL ONLY</span></div>';bind()}
function bind(){document.querySelectorAll('[data-document-source]').forEach(b=>b.onclick=async()=>{try{const doc=await api('/api/document?id='+encodeURIComponent(b.dataset.documentSource));dialog(`<h2>${escapeHTML(doc.filename||'文件明細')}</h2><p class="sub">原始辨識欄位，不代表新增一筆交易。</p><pre style="white-space:pre-wrap;font-size:12px">${escapeHTML(JSON.stringify(doc.metadata,null,2))}</pre><button class="btn" data-close>關閉</button>`)}catch(err){notice(err.message)}});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>goto(b.dataset.page));el('#monthPicker')?.addEventListener('change',async e=>{const next=e.target.value,ticket=++statsRequest;try{const stats=await api('/api/stats?month='+encodeURIComponent(next));if(ticket!==statsRequest)return;summary=stats;month=next;lastError='';draw()}catch(err){if(ticket!==statsRequest)return;lastError=err.message;draw()}});el('#chooseFiles')?.addEventListener('click',e=>{e.stopPropagation();if(!busy)el('#uploadFiles').click()});const drop=el('#dropZone');if(drop){drop.onclick=()=>{if(!busy)el('#uploadFiles').click()};drop.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();if(!busy)el('#uploadFiles').click()}};drop.ondragover=e=>e.preventDefault();drop.ondrop=e=>{e.preventDefault();readFiles(e.dataTransfer.files)}}document.querySelectorAll('[data-field]').forEach(input=>input.oninput=()=>{pending[+input.dataset.doc].transactions[+input.dataset.row][input.dataset.field]=input.type==='checkbox'?input.checked:input.value});document.querySelectorAll('[data-discard]').forEach(b=>b.onclick=()=>{pending.splice(+b.dataset.discard,1);draw();notice('已移出此畫面，未入帳；重新上傳相同文件可再次取得待覆核結果')});document.querySelectorAll('[data-commit]').forEach(b=>b.onclick=()=>confirmDocument(+b.dataset.commit));document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>sourceDialog(b.dataset.source));document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editTransaction(b.dataset.edit));el('#jsonExport')?.addEventListener('click',async()=>{try{download('ledger-database-export.json',JSON.stringify(await api('/api/backup'),null,2),'application/json')}catch(err){notice(err.message)}});el('#csvExport')?.addEventListener('click',exportCSV)}
function dialog(html){el('#dialog').innerHTML=html;const title=el('#dialog').querySelector('h2');if(title){title.id='modalHeading';el('#dialog').setAttribute('aria-labelledby','modalHeading')}el('#dialog').showModal();el('#dialog').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>el('#dialog').close())}
async function sourceDialog(id){const t=db.transactions.find(t=>t.id===id);if(!t)return;let details='',warning='';try{const doc=await api('/api/document?id='+encodeURIComponent(t.document_id));details=`<details open><summary>文件核對明細（原始辨識結果）</summary><pre style="white-space:pre-wrap;font-size:11px">${escapeHTML(JSON.stringify(doc.metadata,null,2))}</pre></details>`}catch(err){warning=`<p class="error">文件明細讀取失敗：${escapeHTML(err.message)}</p>`}dialog(`<h2>交易來源</h2><div class="note">${escapeHTML(t.source)}<br>${t.page?'PDF第 '+escapeHTML(t.page)+' 頁':'CSV第 '+escapeHTML(t.line||'—')+' 列'}<br>${escapeHTML(t.date)} · ${escapeHTML(t.name)} · NT$ ${fmt(t.amount)}</div>${warning}${details}<p class="sub muted">上方交易為已覆核資料；展開區為原始文件欄位，保留薪資扣繳核對資訊。原始文件未留存。</p><button class="btn" data-close>關閉</button>`)}
function editTransaction(id){const t=db.transactions.find(t=>t.id===id);if(!t)return;dialog(`<h2>編輯已入帳交易</h2><form id="editForm"><div class="field"><label for="editDate">日期</label><input type="date" id="editDate" value="${escapeHTML(t.date)}" required></div><div class="field"><label for="editName">摘要</label><input id="editName" value="${escapeHTML(t.name)}" maxlength="150" required></div><div class="field"><label for="editAmount">金額（最多兩位小數）</label><input id="editAmount" type="number" step="0.01" value="${escapeHTML(t.amount)}" required></div><div class="field"><label for="editCategory">分類</label><select id="editCategory">${cats.map(c=>`<option ${t.category===c?'selected':''}>${c}</option>`).join('')}</select></div><p id="editError" class="error" role="alert"></p><div class="actions"><button type="button" class="btn" data-close>取消</button><button class="btn primary" id="saveEdit">儲存至資料庫</button></div></form>`);el('#editForm').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;let saved=false;el('#dialog').querySelectorAll('input,select,button').forEach(i=>i.disabled=true);el('#dialog').oncancel=e=>{if(busy)e.preventDefault()};try{await api('/api/transaction',{id,transaction:{date:el('#editDate').value,name:el('#editName').value,amount:el('#editAmount').value,category:el('#editCategory').value}});saved=true;el('#dialog').close();await reload();lastError='';draw();notice('交易已由後端確認並寫入 SQLite')}catch(err){if(saved){lastError='交易已寫入資料庫，但畫面更新失敗。請重新整理，勿重複修改。'+err.message;draw();notice(lastError)}else{el('#editError').textContent=err.message;el('#dialog').querySelectorAll('input,select,button').forEach(i=>i.disabled=false)}}finally{busy=false}}}
async function readFiles(files){if(busy){notice('正在處理檔案，請稍候');return}busy=true;fileResults=[];draw();try{for(const file of files){try{if(file.size>5*1024*1024)throw Error('單檔上限5 MiB');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const result=await api('/api/upload',{filename:file.name,content_base64:btoa(binary)});if(result.status==='committed'){fileResults.push({ok:true,message:file.name+'：此文件已入帳，未新增交易'})}else if(pending.some(d=>d.document_id===result.document_id)){fileResults.push({ok:true,message:file.name+'：已在待覆核清單'})}else{pending.push(result);fileResults.push({ok:true,message:file.name+'：解析完成，尚未入帳'})}}catch(err){fileResults.push({ok:false,message:file.name+'：'+err.message})}}}finally{busy=false;el('#uploadFiles').value='';draw()}}
async function confirmDocument(index){if(busy)return;const d=pending[index];busy=true;lastError='';draw();try{await api('/api/commit',{document_id:d.document_id,transactions:d.transactions});pending.splice(index,1);if(d.transactions[0])month=d.transactions[0].date.slice(0,7);try{await reload();notice('資料庫已確認入帳，統計已重新計算')}catch(err){month=summary.month||month;lastError='已入帳，但更新畫面失敗。請重新整理，勿重複建立交易。'+err.message}draw()}catch(err){lastError=err.message;notice(err.message)}finally{busy=false;draw()}}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function exportCSV(){const cell=v=>{let s=String(v);if(/^\s*[=+@-]/.test(s)&&!/^\-?\d+(\.\d+)?$/.test(s)||/^[\t\r\n]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};download('ledger-'+month+'.csv','\uFEFFdate,description,amount,category,source\r\n'+db.transactions.filter(t=>t.date.startsWith(month)).map(t=>[t.date,t.name,t.amount,t.category,t.source].map(cell).join(',')).join('\r\n'),'text/csv')}
el('#uploadFiles').onchange=e=>readFiles(e.target.files);window.addEventListener('beforeunload',e=>{if(pending.length||busy){e.preventDefault();e.returnValue=''}});
